import { createForks, teardownForks } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand, ListObjectsV2Command } from "@aws-sdk/client-s3";
import { writeFile } from "fs/promises";
import { join } from "path";

async function main() {
  const sourceBucket = "gold-source";
  const endpoint = "https://t3.storage.dev";
  const region = "auto";
  const adminAccessKeyId = process.env.TIGRIS_STORAGE_ACCESS_KEY_ID;
  const adminSecretAccessKey = process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY;

  if (!adminAccessKeyId || !adminSecretAccessKey) {
    throw new Error("Missing admin credentials");
  }

  let forkSet;
  try {
    console.log("Creating 3 forks...");
    const result = await createForks(sourceBucket, 3, {
      prefix: "audit-fork",
      credentials: { role: "Editor" },
    });

    if (result.error) {
      throw new Error(`Failed to create forks: ${result.error.message}`);
    }

    forkSet = result.forkSet;
    const forks = forkSet.forks;

    console.log("Uploading files to forks in parallel...");
    await Promise.all(
      forks.map(async (fork, index) => {
        const s3 = new S3Client({
          endpoint,
          region,
          credentials: {
            accessKeyId: fork.credentials.accessKeyId,
            secretAccessKey: fork.credentials.secretAccessKey,
          },
        });

        const key = `agent-${index + 1}.out`;
        await s3.send(
          new PutObjectCommand({
            Bucket: fork.bucketName,
            Key: key,
            Body: `Content from agent ${index + 1}`,
          })
        );
        console.log(`Uploaded ${key} to ${fork.bucketName}`);
      })
    );

    console.log("Auditing bucket states...");
    const auditReport: any = {
      source_keys: [],
      fork_results: [],
    };

    // Audit source bucket
    const adminS3 = new S3Client({
      endpoint,
      region,
      credentials: {
        accessKeyId: adminAccessKeyId,
        secretAccessKey: adminSecretAccessKey,
      },
    });

    const sourceObjects = await adminS3.send(
      new ListObjectsV2Command({ Bucket: sourceBucket })
    );
    auditReport.source_keys = (sourceObjects.Contents || [])
      .map((c) => c.Key!)
      .sort();

    // Verify source bucket invariants
    if (
      auditReport.source_keys.length !== 2 ||
      !auditReport.source_keys.includes("seed1.txt") ||
      !auditReport.source_keys.includes("seed2.txt")
    ) {
      throw new Error(
        `Source bucket isolation failure: expected [seed1.txt, seed2.txt], got [${auditReport.source_keys.join(
          ", "
        )}]`
      );
    }

    // Audit forks
    for (let i = 0; i < forks.length; i++) {
      const fork = forks[i];
      const forkS3 = new S3Client({
        endpoint,
        region,
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });

      const forkObjects = await forkS3.send(
        new ListObjectsV2Command({ Bucket: fork.bucketName })
      );
      const keys = (forkObjects.Contents || []).map((c) => c.Key!).sort();
      auditReport.fork_results.push({
        bucket: fork.bucketName,
        keys: keys,
      });

      // Verify fork invariants
      const expectedOwnKey = `agent-${i + 1}.out`;
      if (!keys.includes(expectedOwnKey)) {
        throw new Error(`Fork ${i} missing its own key ${expectedOwnKey}`);
      }
      if (!keys.includes("seed1.txt") || !keys.includes("seed2.txt")) {
        throw new Error(`Fork ${i} missing seed files`);
      }
      if (keys.length !== 3) {
        throw new Error(
          `Fork ${i} has unexpected number of keys: expected 3, got ${keys.length} ([${keys.join(
            ", "
          )}])`
        );
      }
      // Check for other forks' keys
      for (let j = 0; j < forks.length; j++) {
        if (i === j) continue;
        const otherKey = `agent-${j + 1}.out`;
        if (keys.includes(otherKey)) {
          throw new Error(`Fork ${i} contains key from fork ${j}: ${otherKey}`);
        }
      }
    }

    console.log("Writing audit report...");
    await writeFile(
      "/home/user/isolation/audit.json",
      JSON.stringify(auditReport, null, 2),
      "utf-8"
    );
    console.log("Audit report written to /home/user/isolation/audit.json");
  } finally {
    if (forkSet) {
      console.log("Tearing down forks...");
      await teardownForks(forkSet);
      console.log("Forks torn down.");
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

