import { createWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand, ListObjectsV2Command, DeleteObjectCommand, DeleteBucketCommand } from "@aws-sdk/client-s3";

async function setup() {
  const bucketName = "gold-source";
  const s3 = new S3Client({
    endpoint: "https://t3.storage.dev",
    region: "auto",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  try {
    console.log(`Deleting existing bucket ${bucketName} if it exists...`);
    let isTruncated = true;
    let continuationToken = undefined;
    while (isTruncated) {
      const objects = await s3.send(new ListObjectsV2Command({ 
        Bucket: bucketName,
        ContinuationToken: continuationToken
      }));
      if (objects.Contents) {
        for (const obj of objects.Contents) {
          await s3.send(new DeleteObjectCommand({ Bucket: bucketName, Key: obj.Key! }));
        }
      }
      isTruncated = objects.IsTruncated || false;
      continuationToken = objects.NextContinuationToken;
    }
    await s3.send(new DeleteBucketCommand({ Bucket: bucketName }));
    console.log(`Bucket ${bucketName} deleted.`);
  } catch (err) {
    console.log(`Note: bucket deletion skipped or failed: ${err}`);
  }

  console.log(`Creating workspace ${bucketName} with snapshots enabled...`);

  const result = await createWorkspace(bucketName, {
    enableSnapshots: true,
  });

  if (result.error) {
    console.error("Failed to create workspace:", result.error);
    // If it already exists, check if snapshots are enabled? No easy way.
    // Let's try to proceed if it's already there.
    if (result.error.message?.includes("already exists") || result.error.message?.includes("not available")) {
        console.log("Proceeding with existing bucket...");
    } else {
        process.exit(1);
    }
  } else {
    const workspace = result.data;
    console.log(`Workspace ${workspace.bucket} created.`);
  }

  console.log("Uploading seeds...");
  await s3.send(new PutObjectCommand({
    Bucket: bucketName,
    Key: "seed1.txt",
    Body: "gold-source seed object number one.\n",
  }));
  await s3.send(new PutObjectCommand({
    Bucket: bucketName,
    Key: "seed2.txt",
    Body: "gold-source seed object number two.\n",
  }));
  console.log("Seeds uploaded.");
}

setup().catch(err => {
  console.error(err);
  process.exit(1);
});

